package com.axiom.integrations.testreport.junit;
import com.axiom.domain.test.*;import com.axiom.integrations.testreport.TestReportParser;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.xml.XMLConstants;import javax.xml.parsers.*;import org.springframework.stereotype.Component;import org.w3c.dom.*;
@Component public class JUnitXmlTestReportParser implements TestReportParser {public TestReport parse(String source,byte[] bytes,String hint){if(bytes.length>25_000_000)throw new IllegalArgumentException("Test report exceeds 25 MB limit.");try{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING,true);f.setXIncludeAware(false);f.setExpandEntityReferences(false);Document d=f.newDocumentBuilder().parse(new ByteArrayInputStream(bytes));List<TestSuite> suites=new ArrayList<>();NodeList nodes=d.getElementsByTagName("testsuite");for(int i=0;i<nodes.getLength();i++)suites.add(suite((Element)nodes.item(i)));return new TestReport(hint,source,suites);}catch(Exception e){throw new IllegalArgumentException("Invalid or unsafe JUnit XML report.",e);}}
private TestSuite suite(Element s){List<TestCaseExecution> cases=new ArrayList<>();NodeList list=s.getElementsByTagName("testcase");for(int i=0;i<list.getLength();i++){Element t=(Element)list.item(i);Element issue=child(t,"failure");TestStatus status=TestStatus.PASSED;if(issue==null){issue=child(t,"error");if(issue!=null)status=TestStatus.ERROR;else if(child(t,"skipped")!=null)status=TestStatus.SKIPPED;}else status=TestStatus.FAILED;String msg=issue==null?null:issue.getAttribute("message");String type=issue==null?null:issue.getAttribute("type");String normalized=msg==null?null:msg.replaceAll("\\b\\d{4,}\\b","<NUMBER>");cases.add(new TestCaseExecution(id(t.getAttribute("classname"),s.getAttribute("name"),t.getAttribute("name")),t.getAttribute("classname"),t.getAttribute("name"),s.getAttribute("name"),status,millis(t.getAttribute("time")),type,msg,normalized,issue==null?null:issue.getTextContent(),null));}return new TestSuite(s.getAttribute("name"),cases);}private Element child(Element e,String tag){NodeList n=e.getElementsByTagName(tag);return n.getLength()==0?null:(Element)n.item(0);}private long millis(String s){try{return Math.round(Double.parseDouble(s)*1000);}catch(Exception e){return 0;}}private String id(String c,String s,String n){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(("test-id-v1|"+c+"|"+s+"|"+n).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
